$wgHooks['SiteNoticeAfter'][] = static function ( &$siteNotice, $skin ) {
	global $wgREWikiGatewayUrl;
	$llms = "$wgREWikiGatewayUrl/llms.txt";
	$connect = \MediaWiki\Title\Title::newFromText( 'REWiki:Connect' );
	$skill = "$wgREWikiGatewayUrl/skill/rewiki/SKILL.md";
	$siteNotice .= Html::rawElement( 'div', [ 'class' => 'rewiki-agent-notice', 'style' => 'font-size:85%; margin:0.2em 0;' ],
		'Setting up an AI agent? ReverseEngineering.wiki skill (works from the command line, no configuration): '
		. Html::element( 'a', [ 'href' => $skill ], $skill )
		. ' · setup for every client, including MCP: '
		. Html::element( 'a', [ 'href' => $llms ], $llms )
		. ' · ' . Html::element( 'a', [ 'href' => $connect->getLocalURL() ], 'REWiki:Connect' )
	);
	return true;
};

