};

final class REWikiPolicy {
	private static ?array $rules = null;

	/** @return array<int, array{id: string, label: string, line: int}> */
	public static function check( string $text ): array {
		$hits = [];
		foreach ( self::rules() as $rule ) {
			if ( preg_match( $rule['regex'], $text, $m, PREG_OFFSET_CAPTURE ) ) {
				$line = substr_count( substr( $text, 0, $m[0][1] ), "\n" ) + 1;
				$hits[] = [ 'id' => $rule['id'], 'label' => $rule['label'], 'line' => $line ];
			}
		}
		return $hits;
	}

	private static function rules(): array {
		if ( self::$rules !== null ) {
			return self::$rules;
		}
		$data = json_decode( file_get_contents( __DIR__ . '/policy/patterns.json' ), true );
		self::$rules = [];
		foreach ( $data['rules'] as $rule ) {
			if ( empty( $rule['mediawiki'] ) ) {
				continue;
			}
			// JavaScript \u{XXXX} / \uXXXX escapes → PCRE \x{XXXX}.
			$pattern = preg_replace( '/\\\\u\{([0-9A-Fa-f]+)\}/', '\\x{$1}', $rule['pattern'] );
			$pattern = preg_replace( '/\\\\u([0-9A-Fa-f]{4})/', '\\x{$1}', $pattern );
			$flags = str_replace( 'u', '', $rule['flags'] ) . 'u';
			self::$rules[] = [
				'id' => $rule['id'],
				'label' => $rule['label'],
				'regex' => '/' . str_replace( '/', '\\/', $pattern ) . '/' . $flags,
			];
		}
		return self::$rules;
	}
}
